// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListBabies Babies in the caller's active family, oldest first.
	// (GET /api/babies)
	ListBabies(ctx context.Context, request ListBabiesRequestObject) (ListBabiesResponseObject, error)
	// CreateBaby Create a baby in the caller's active family. Free — no plan gate.
	// (POST /api/babies)
	CreateBaby(ctx context.Context, request CreateBabyRequestObject) (CreateBabyResponseObject, error)
	// DeleteBaby Family-admin only. Deletes the baby and EVERY log for them (cascade).
	// (DELETE /api/babies/{id})
	DeleteBaby(ctx context.Context, request DeleteBabyRequestObject) (DeleteBabyResponseObject, error)
	// UpdateBaby Partial update. An empty body is a no-op that returns the baby unchanged.
	// (PATCH /api/babies/{id})
	UpdateBaby(ctx context.Context, request UpdateBabyRequestObject) (UpdateBabyResponseObject, error)
	// ListDiapers Diaper logs in the caller's active family, newest first.
	// (GET /api/diapers)
	ListDiapers(ctx context.Context, request ListDiapersRequestObject) (ListDiapersResponseObject, error)
	// CreateDiaper Log a diaper change for a baby in the caller's active family.
	// (POST /api/diapers)
	CreateDiaper(ctx context.Context, request CreateDiaperRequestObject) (CreateDiaperResponseObject, error)
	// DeleteDiaper Delete a diaper log.
	// (DELETE /api/diapers/{id})
	DeleteDiaper(ctx context.Context, request DeleteDiaperRequestObject) (DeleteDiaperResponseObject, error)
	// UpdateDiaper Partial update. A field sent as `null` clears the column; an omitted field is left unchanged; an empty body is a no-op that returns the diaper log unchanged. `time`/`type` are not nullable — only settable or omitted. See internal/api/feeds.go for how this endpoint tells "omitted" apart from "null" (the generated request type alone cannot).
	// (PATCH /api/diapers/{id})
	UpdateDiaper(ctx context.Context, request UpdateDiaperRequestObject) (UpdateDiaperResponseObject, error)
	// GetFamily The caller's active family.
	// (GET /api/family)
	GetFamily(ctx context.Context, request GetFamilyRequestObject) (GetFamilyResponseObject, error)
	// ListFamilyMembers Caretakers in the caller's active family.
	// (GET /api/family/members)
	ListFamilyMembers(ctx context.Context, request ListFamilyMembersRequestObject) (ListFamilyMembersResponseObject, error)
	// DeleteFamilyMember Remove a member from the caller's active family. Family-admin only.
	// (DELETE /api/family/members/{memberId})
	DeleteFamilyMember(ctx context.Context, request DeleteFamilyMemberRequestObject) (DeleteFamilyMemberResponseObject, error)
	// SetFamilyMemberRole Change a member's role in the caller's active family. Family-admin only.
	// (POST /api/family/members/{memberId}/role)
	SetFamilyMemberRole(ctx context.Context, request SetFamilyMemberRoleRequestObject) (SetFamilyMemberRoleResponseObject, error)
	// ListFeeds Feed logs in the caller's active family, newest first.
	// (GET /api/feeds)
	ListFeeds(ctx context.Context, request ListFeedsRequestObject) (ListFeedsResponseObject, error)
	// CreateFeed Log a feed for a baby in the caller's active family.
	// (POST /api/feeds)
	CreateFeed(ctx context.Context, request CreateFeedRequestObject) (CreateFeedResponseObject, error)
	// DeleteFeed Delete a feed log.
	// (DELETE /api/feeds/{id})
	DeleteFeed(ctx context.Context, request DeleteFeedRequestObject) (DeleteFeedResponseObject, error)
	// UpdateFeed Partial update. A field sent as `null` clears the column; an omitted field is left unchanged; an empty body is a no-op that returns the feed unchanged. `time`/`type` are not nullable — only settable or omitted. See internal/api/feeds.go for how this endpoint tells "omitted" apart from "null" (the generated request type alone cannot).
	// (PATCH /api/feeds/{id})
	UpdateFeed(ctx context.Context, request UpdateFeedRequestObject) (UpdateFeedResponseObject, error)
	// GetMe Session info for the SPA shell. Requires a session but NOT an active family — the family/member/plan fields are null when the caller has none.
	// (GET /api/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListSleeps Sleep logs in the caller's active family, newest first (by startTime).
	// (GET /api/sleep)
	ListSleeps(ctx context.Context, request ListSleepsRequestObject) (ListSleepsResponseObject, error)
	// CreateSleep Create a sleep log. Omit endTime to start an active session; a baby can only have one active session at a time — enforced by a partial unique index (see internal/api/sleep.go), not just the pre-check this endpoint also does.
	// (POST /api/sleep)
	CreateSleep(ctx context.Context, request CreateSleepRequestObject) (CreateSleepResponseObject, error)
	// ListSleepLocations Custom sleep-location chips for the caller's active family.
	// (GET /api/sleep-locations)
	ListSleepLocations(ctx context.Context, request ListSleepLocationsRequestObject) (ListSleepLocationsResponseObject, error)
	// CreateSleepLocation Family-admin only; not available to API keys. Rejects a name that duplicates a default chip or an existing custom one (case-insensitive), and caps custom locations at 20 per family.
	// (POST /api/sleep-locations)
	CreateSleepLocation(ctx context.Context, request CreateSleepLocationRequestObject) (CreateSleepLocationResponseObject, error)
	// DeleteSleepLocation Family-admin only; not available to API keys.
	// (DELETE /api/sleep-locations/{id})
	DeleteSleepLocation(ctx context.Context, request DeleteSleepLocationRequestObject) (DeleteSleepLocationResponseObject, error)
	// GetActiveSleep The active sleep session for a baby, or null.
	// (GET /api/sleep/active)
	GetActiveSleep(ctx context.Context, request GetActiveSleepRequestObject) (GetActiveSleepResponseObject, error)
	// DeleteSleep Delete a sleep log.
	// (DELETE /api/sleep/{id})
	DeleteSleep(ctx context.Context, request DeleteSleepRequestObject) (DeleteSleepResponseObject, error)
	// UpdateSleep Partial update. `endTime` sent as `null` CLEARS it, reopening the session — subject to the same one-active-session-per-baby constraint as create, so this can also 409. `location`/`notes` may also be sent as `null` to clear them; `startTime` is not nullable — only settable or omitted. See internal/api/feeds.go for the omitted-vs-null presence-detection pattern this endpoint needs.
	// (PATCH /api/sleep/{id})
	UpdateSleep(ctx context.Context, request UpdateSleepRequestObject) (UpdateSleepResponseObject, error)
	// WakeSleep End the active session for a sleep log. endTime defaults to now.
	// (POST /api/sleep/{id}/wake)
	WakeSleep(ctx context.Context, request WakeSleepRequestObject) (WakeSleepResponseObject, error)
	// GetSummary Everything the home screen needs in one call: last feed, last diaper, active + last sleep, active play, and today's local-day totals.
	// (GET /api/summary)
	GetSummary(ctx context.Context, request GetSummaryRequestObject) (GetSummaryResponseObject, error)
	// Healthz Liveness probe. Touches nothing — not even the database pool.
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
	// Readyz Readiness probe. Runs `SELECT 1` against the database pool.
	// (GET /readyz)
	Readyz(ctx context.Context, request ReadyzRequestObject) (ReadyzResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

